def is_anagram(word1, word2):
    """Receives two words and returns True/False (boolean) if word2 is
       an anagram of word1, ignore case and spacing.
       About anagrams: https://en.wikipedia.org/wiki/Anagram"""

    # short way
    # word1 = word1.strip().replace(' ', '').lower()
    # word2 = word2.strip().replace(' ', '').lower()
    # return sorted(word1) == sorted(word2)

    # longer way
    word1 = word1.strip().replace(' ', '').lower()
    word2 = word2.strip().replace(' ', '').lower()

    if len(word1) != len(word2):
        return False

    count = {}

    for letter in word1:
        if letter in count:
            count[letter] += 1
        else:
            count[letter] = 1

    for letter in word2:
        if letter in count:
            count[letter] -= 1
        else:
            count[letter] = 1

    for c in count:
        if count[c] != 0:
            return False
    return True

